import React, { Suspense } from 'react';
import { MemoryRouter, Routes, Route, Navigate, useParams } from 'react-router-dom';
import { Provider } from 'react-redux';
import { store } from './store/store';
import { ProtectedRoute } from './components/auth/ProtectedRoute';
import { AppLayout } from './components/layout/AppLayout';
import { SimpleNotFoundPage } from './components/layout/SimpleNotFoundPage';
import { isStandalone, showDevNav } from './dev/isStandalone';
import { StandaloneMockNav } from './standalone/StandaloneMockNav';
import { StandaloneAuthBootstrap } from './standalone/StandaloneAuthBootstrap';
import { RouterSync } from './routing/RouterSync';
import { scykRoutes } from './config/scykRoutes';
import MedicalIncidentsListPage from './pages/MedicalIncidentsListPage';
import MedicalIncidentFormPage from './pages/MedicalIncidentFormPage';
import MedicalIncidentReportPage from './pages/MedicalIncidentReportPage';
import ServiceMismatchReportPage from './pages/ServiceMismatchReportPage';
import FallIncidentReportPage from './pages/FallIncidentReportPage';
import DailyIncidentReportsListPage from './pages/DailyIncidentReportsListPage';
import DailyIncidentReportFormPage from './pages/DailyIncidentReportFormPage';
import FallLocationWarningListPage from './pages/FallLocationWarningListPage';
import FallLocationWarningFormPage from './pages/FallLocationWarningFormPage';
import MonthlyReportListPage from './pages/MonthlyReportListPage';
import MonthlyReportFormPage from './pages/MonthlyReportFormPage';
import { ToastProvider, ReduxToastContainer, AlertProvider } from '@linm-soft/common-components';

const DevPage = React.lazy(() => import('./dev/DevPage'));

const PageSuspense = ({ children }: { children: React.ReactNode }) => (
  <Suspense fallback={<div style={{ padding: '2rem' }}>Đang tải...</div>}>
    {children}
  </Suspense>
);

const AppShell = () => (
  <>
    {isStandalone && <StandaloneMockNav />}
    <AppLayout />
  </>
);

const layoutElement = isStandalone ? (
  <AppShell />
) : (
  <ProtectedRoute>
    <AppLayout />
  </ProtectedRoute>
);

const initialPath = window.location.pathname + window.location.search || '/';

const LegacyMonthlyReportRedirect = () => {
  const { id } = useParams();
  return <Navigate to={id ? scykRoutes.monthlyReports.detail(id) : scykRoutes.monthlyReports.list} replace />;
};

const LegacyIncidentDetailRedirect = () => {
  const { id } = useParams();
  return <Navigate to={id ? scykRoutes.incidents.detail(id) : scykRoutes.incidents.list} replace />;
};

const LegacyFallWarningDetailRedirect = () => {
  const { id } = useParams();
  return <Navigate to={id ? scykRoutes.fallWarnings.detail(id) : scykRoutes.fallWarnings.list} replace />;
};

const legacyRedirects = (
  <>
    <Route path="medical-incidents" element={<Navigate to={scykRoutes.incidents.list} replace />} />
    <Route path="medical-incidents/new" element={<Navigate to={scykRoutes.incidents.new} replace />} />
    <Route path="medical-incidents/reports" element={<Navigate to={scykRoutes.reports.summary} replace />} />
    <Route path="medical-incidents/reports/service-mismatch" element={<Navigate to={scykRoutes.reports.serviceMismatch} replace />} />
    <Route path="medical-incidents/reports/fall" element={<Navigate to={scykRoutes.reports.fall} replace />} />
    <Route path="medical-incidents/daily-reports" element={<Navigate to={scykRoutes.dailyReports.list} replace />} />
    <Route path="medical-incidents/daily-reports/new" element={<Navigate to={scykRoutes.dailyReports.new} replace />} />
    <Route path="medical-incidents/monthly-reports" element={<Navigate to={scykRoutes.monthlyReports.list} replace />} />
    <Route path="medical-incidents/monthly-reports/new" element={<Navigate to={scykRoutes.monthlyReports.new} replace />} />
    <Route path="medical-incidents/monthly-reports/:id" element={<LegacyMonthlyReportRedirect />} />
    <Route path="medical-incidents/:id" element={<LegacyIncidentDetailRedirect />} />
    <Route path="fall-location-warnings" element={<Navigate to={scykRoutes.fallWarnings.list} replace />} />
    <Route path="fall-location-warnings/new" element={<Navigate to={scykRoutes.fallWarnings.new} replace />} />
    <Route path="fall-location-warnings/:id" element={<LegacyFallWarningDetailRedirect />} />
  </>
);

const Root: React.FC = () => {
  const routes = (
    <MemoryRouter initialEntries={[initialPath]} initialIndex={0} future={{ v7_startTransition: true, v7_relativeSplatPath: true }}>
      {!isStandalone && <RouterSync />}
      <Routes>
        <Route path="/" element={layoutElement}>
          {showDevNav && (
            <>
              <Route index element={<Navigate to="/dev" replace />} />
              <Route path="dev" element={<PageSuspense><DevPage /></PageSuspense>} />
            </>
          )}
          {legacyRedirects}
          <Route path="scyk/su-co" element={<MedicalIncidentsListPage />} />
          <Route path="scyk/su-co/new" element={<MedicalIncidentFormPage />} />
          <Route path="scyk/su-co/:id" element={<MedicalIncidentFormPage />} />
          <Route path="scyk/bc/thong-ke" element={<MedicalIncidentReportPage />} />
          <Route path="scyk/bc/nham-dv" element={<ServiceMismatchReportPage />} />
          <Route path="scyk/bc/te-nga" element={<FallIncidentReportPage />} />
          <Route path="scyk/bc/hang-ngay" element={<DailyIncidentReportsListPage />} />
          <Route path="scyk/bc/hang-ngay/new" element={<DailyIncidentReportFormPage />} />
          <Route path="scyk/bc/tong-hop-thang" element={<MonthlyReportListPage />} />
          <Route path="scyk/bc/tong-hop-thang/new" element={<MonthlyReportFormPage />} />
          <Route path="scyk/bc/tong-hop-thang/:id" element={<MonthlyReportFormPage />} />
          <Route path="scyk/canh-bao/te-nga" element={<FallLocationWarningListPage />} />
          <Route path="scyk/canh-bao/te-nga/new" element={<FallLocationWarningFormPage />} />
          <Route path="scyk/canh-bao/te-nga/:id" element={<FallLocationWarningFormPage />} />
          <Route path="*" element={<SimpleNotFoundPage />} />
        </Route>
      </Routes>
    </MemoryRouter>
  );

  return (
    <Provider store={store}>
      <AlertProvider>
        <ToastProvider>
          <ReduxToastContainer />
          {isStandalone ? (
            <StandaloneAuthBootstrap>{routes}</StandaloneAuthBootstrap>
          ) : (
            routes
          )}
        </ToastProvider>
      </AlertProvider>
    </Provider>
  );
};

export default Root;
