/**
 * SCYK UI routes — aligned with Auth menu_items.csv (medical-incidents set).
 * API paths remain /medical-incidents/* on BFF; only shell URLs use /scyk/*.
 */
export const SCYK_HOME = '/scyk/su-co';

export const scykRoutes = {
  home: SCYK_HOME,
  incidents: {
    list: '/scyk/su-co',
    new: '/scyk/su-co/new',
    detail: (id: string) => `/scyk/su-co/${id}`,
  },
  fallWarnings: {
    list: '/scyk/canh-bao/te-nga',
    new: '/scyk/canh-bao/te-nga/new',
    detail: (id: string) => `/scyk/canh-bao/te-nga/${id}`,
  },
  dailyReports: {
    list: '/scyk/bc/hang-ngay',
    new: '/scyk/bc/hang-ngay/new',
  },
  monthlyReports: {
    list: '/scyk/bc/tong-hop-thang',
    new: '/scyk/bc/tong-hop-thang/new',
    detail: (id: string) => `/scyk/bc/tong-hop-thang/${id}`,
  },
  reports: {
    summary: '/scyk/bc/thong-ke',
    serviceMismatch: '/scyk/bc/nham-dv',
    fall: '/scyk/bc/te-nga',
  },
} as const;

/** Shell / sidebar path detection (includes legacy paths during redirect). */
export function isScykShellPath(pathname: string): boolean {
  return (
    pathname.startsWith('/scyk/')
    || pathname.startsWith('/medical-incidents')
    || pathname.startsWith('/fall-location-warnings')
  );
}
